import { useState } from 'react';
import dayjs from 'dayjs';
import * as XLSX from 'xlsx';
import { UploadChangeParam } from 'antd/es/upload';
import { SpecType, IssueType, PriorityTypeEnum, ProgressTypeEnum } from './types';
import { SheetsHookType, TableHookType, Sheets } from './types';

// TODO: relations
export const useSheets = (sheets : Sheets): SheetsHookType => {
  const readExcelFile = (file: File): Promise<{[sheetName: string] : any[]}> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const data = new Uint8Array(e.target!.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const jsonData = workbook.SheetNames.reduce<Record<string, any[]>>((acc, sheetName) => {
          acc[sheetName] = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName])
          return acc;
        }, {})
        resolve(jsonData)
      };
      reader.onerror = (error) => reject(error);
      reader.readAsArrayBuffer(file);
    });
  };

  const loadSheets = (info: UploadChangeParam) => {
    /* ここにExcelからデータを吸い出してjsonの配列にまとめる処理を書く */
    readExcelFile(info.file.originFileObj as File).then((jsonData) => {
      Object.entries(jsonData).forEach(([sheetName, items]) => {
        sheets[sheetName].setItems(sheets[sheetName].refineLoadItems(items))
      })
    })
  }

  const saveSheets = () => {
    const wb = XLSX.utils.book_new();
    Object.entries(sheets).forEach(([sheetName, table]) => {
      const ws = XLSX.utils.json_to_sheet(table.exportItems());
      XLSX.utils.book_append_sheet(wb, ws, sheetName);
    })
    XLSX.writeFile(wb, `emanager_${dayjs().format('YYYYMMDDHHmmss')}.xlsx`);
  }

  return {loadSheets, saveSheets}
}

export const useSpecs = (): TableHookType<SpecType> => {
  const [items, setItems] = useState<SpecType[]>([]);

  const addItem = (spec: SpecType) => {
    setItems([...items, spec]);
  }

  const addEmptyItem = () => {
    const new_spec: SpecType = {
      key: items.length === 0 ? "1" : (parseInt(items[0].key) + 1).toString(),
      related_issue_key: [],
      title: "New",
      outage_date: dayjs(),
      abstract: "",
      statement: "",
      comments: "",
      progress: ProgressTypeEnum.New,
      priority: PriorityTypeEnum.Middle,
      system_tags: [],
      ticket_id: "",
      ticket_link: "",
      due_date: dayjs(),
      elapsed_days: 0,
      remaining_days: 0,
      creation_date: dayjs(),
      closed_date: null,
    };
    setItems([new_spec, ...items]);

    return new_spec.key;
  }

  const editItem = (key: string, spec: SpecType) => {
    setItems(items.map(i => i.key === key ? spec : i));
  }

  const deleteItem = (key: string) => {
    setItems(items.filter(i => i.key !== key));
  }

  const refineLoadItems = (data: any[]): SpecType[] => { 
    return data.map((item) => ({
      key: item.key.toString(),
      related_issue_key: item.related_issue_key === undefined ? [] : item.related_issue_key.toString().split(/\r\n|\n|\r/),
      title: item.title,
      outage_date: dayjs(item.outage_date),
      abstract: item.abstract,
      statement: item.statement,
      comments: item.comments,
      progress: item.progress,
      priority: item.priority,
      system_tags: item.system_tags === undefined ? [] : item.system_tags.split(/\r\n|\n|\r/),
      ticket_id: item.ticket_id,
      ticket_link: item.ticket_link,
      due_date: dayjs(item.due_date),
      elapsed_days: dayjs().diff(dayjs(item.outage_date), 'day'),
      remaining_days: dayjs(item.due_date).diff(dayjs(), 'day') + 1,
      creation_date: dayjs(item.creation_date),
      closed_date: item.closed_date === "Not closed yet" ? null : dayjs(item.closed_date),
    }));
  }
  const exportItems = () => {
    /* ここにjsonの配列をExcelに書き出す処理を書く */
    // TODO: Primitive Obsession
    // TODO: Data Clumps
    return [
      ...items.map(spec => ({
          "key": spec.key,
          "related_issue_key": spec.related_issue_key.join('\n'),
          "title": spec.title,
          "outage_date": spec.outage_date.format('YYYY/MM/DD'),
          "abstract": spec.abstract,
          "statement": spec.statement,
          "comments": spec.comments,
          "progress": spec.progress,
          "priority": spec.priority,
          "ticket_id": spec.ticket_id,
          "ticket_link": spec.ticket_link,
          "system_tags": spec.system_tags.length === 0 ? null : spec.system_tags.join('\n'),
          "due_date": spec.due_date.format('YYYY/MM/DD'),
          "elapsed_days": spec.elapsed_days,
          "remaining_days": spec.remaining_days,
          "creation_date": spec.creation_date.format('YYYY/MM/DD'),
          "closed_date": spec.closed_date === null ? "Not closed yet" : spec.closed_date.format('YYYY/MM/DD'),
        })
      ),
    ]
  }

  return {items, setItems, addItem, addEmptyItem, editItem, deleteItem, refineLoadItems, exportItems};
}

