import React, { useState } from "react";
import { EyeOutlined, DeleteOutlined, PlusSquareOutlined, CloseCircleFilled, CheckCircleFilled, SisternodeOutlined, CloseOutlined } from '@ant-design/icons';
import { Button, Typography } from 'antd';
import { Select } from 'antd';
import { Space, Table, Tag} from 'antd'
import { Row, Col } from 'antd';
import { useNavigate } from 'react-router-dom';
import {  IssueType, SpecType, ProgressTypeEnum, PriorityTypeEnum, TableHookType } from "../../types";
import { TableColumnsType } from "antd";
import dayjs, { Dayjs } from 'dayjs';
import Modal from "antd/es/modal/Modal";

export const IssuesPage: React.FC<{issues: TableHookType<IssueType>, specs: TableHookType<SpecType>}> = ({issues, specs}) => {
    const navigate = useNavigate();

    const handleAddEmptyIssue = () => {
        const key = issues.addEmptyItem();
        console.log(key);
    }

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [modalIssueKey, setModalIssueKey] = useState<string>("");
    const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);

    // TODO: Duplicated Code
    const set_progress = (key: string, value: ProgressTypeEnum) => {
        const issue = issues.items.filter(issue => issue.key === key)[0];
        if(value === ProgressTypeEnum.Closed) {
            issues.editItem(key, {...issue, progress: value, closed_date: dayjs()});
        } else {
            issues.editItem(key, {...issue, progress: value, closed_date: null});
        }
    }

    const spec_columns: TableColumnsType<SpecType> = [
        {
            key: 'progress',
            title: 'Progress',
            dataIndex: 'progress',
            filters: [
                { text: ProgressTypeEnum.New, value: ProgressTypeEnum.New },
                { text: ProgressTypeEnum.InProgress, value: ProgressTypeEnum.InProgress },
                { text: ProgressTypeEnum.Resolved, value: ProgressTypeEnum.Resolved },
                { text: ProgressTypeEnum.Closed, value: ProgressTypeEnum.Closed },
            ], 
            onFilter: (value: any, record: SpecType) => record.progress === value,
            render: (status: string, record: SpecType) => (
                <Select defaultValue={status} style={{ width: 120 }} onChange={(value) => set_progress(record.key, value as ProgressTypeEnum)}>
                    <Select.Option value={ProgressTypeEnum.New}>New</Select.Option>
                    <Select.Option value={ProgressTypeEnum.InProgress}>In Progress</Select.Option>
                    <Select.Option value={ProgressTypeEnum.Resolved}>Resolved</Select.Option>
                    <Select.Option value={ProgressTypeEnum.Closed}>Closed</Select.Option>
                </Select>
            )
        },
        {
            key: 'outage_date',
            title: 'Outage date',
            dataIndex: 'outage_date',
            filters: specs.items.map(item => ({ text: item.outage_date.format('YYYY/MM/DD'), value: item.outage_date.format('YYYY/MM/DD') })).filter(
                (item, index, self) => index === self.findIndex((t) => t.value === item.value)
            ),
            filterSearch: true,
            onFilter: (value: any, record: SpecType) => record.outage_date.format('YYYY/MM/DD').includes(value),
            defaultSortOrder: 'descend',
            sorter: (a: SpecType, b: SpecType) => a.outage_date.diff(b.outage_date),
            render: (outage_date: Dayjs) => (
                <>
                    <p>{outage_date.format('YYYY/MM/DD')}</p>
                </>
            )
        },
        {
            key: 'ticket_id',
            title: 'Ticket ID',
            dataIndex: 'ticket_id',
            filters: specs.items.map(item => ({ text: item.ticket_id, value: item.ticket_id })).filter(
                (item, index, self) => index === self.findIndex((t) => t.value === item.value)
            ),
            filterSearch: true,
            onFilter: (value: any, record: SpecType) => record.ticket_id.includes(value),
        },
        {
            key: 'title',
            title: 'Title',
            dataIndex: 'title',
            filters: specs.items.map(item => ({ text: item.title, value: item.title })).filter(
                (item, index, self) => index === self.findIndex((t) => t.value === item.value)
            ),
            filterSearch: true,
            onFilter: (value: any, record: SpecType) => record.title.includes(value),
        },
        {
            key: 'system_tags',
            title: 'Systems',
            dataIndex: 'system_tags',
            filters: specs.items.map(item => item.system_tags.map(tag => ({ text: tag, value: tag }))).flat().filter(
                (item, index, self) => index === self.findIndex((t) => t.value === item.value)
            ),
            filterSearch: true,
            onFilter: (value: any, record: SpecType) => record.system_tags.includes(value),
            render: (tags: string[]) => (
                <>
                    {tags.map(tag => {
                        const color = tag.length > 7 ? 'geekblue' : 
                                      tag.length > 5 ? 'green' :
                                      tag.length > 3 ? 'orange' : 'red'
                        return (
                            <Tag color={color} key={tag}>
                                {tag.toUpperCase()}
                            </Tag>
                        )
                    })}
                </>
            )
        },
        {
            key: 'priority',
            title: 'Priority',
            dataIndex: 'priority',
            filters: [
                { text: PriorityTypeEnum.High, value: PriorityTypeEnum.High },
                { text: PriorityTypeEnum.Middle, value: PriorityTypeEnum.Middle },
                { text: PriorityTypeEnum.Low, value: PriorityTypeEnum.Low },
            ],
            filterSearch: true,
            onFilter: (value: any, record: SpecType) => record.priority.includes(value),
        },
        {
            key: 'elapsed_days',
            title: 'Elapsed days',
            dataIndex: 'elapsed_days',
            sorter: (a: SpecType, b: SpecType) => a.elapsed_days - b.elapsed_days,
            render: (elapsed_days: number, record: SpecType) => (
                record.progress === ProgressTypeEnum.New && elapsed_days >= 7 ? <p style={{color: 'gold'}}>{elapsed_days}</p> : <p style={{color: 'black'}}>{elapsed_days}</p>
            )
        },
        {
            key: 'remaining_days',
            title: 'Remaining days',
            dataIndex: 'remaining_days',
            sorter: (a: SpecType, b: SpecType) => a.remaining_days - b.remaining_days,
            render: (remaining_days: number) => (
                remaining_days <= 0 ? <p style={{color: 'red'}}>{remaining_days}</p> : 
                remaining_days < 7 ? <p style={{color: 'orange'}}>{remaining_days}</p> :
                <p style={{color: 'black'}}>{remaining_days}</p>
            )
        },
        {
            key: 'action',
            title: 'Action',
            dataIndex: 'action',
            fixed: 'right',
            render: (text:String, record: SpecType, index:Number) => (
                <Space size="middle">
                    <Button type='text' icon={<EyeOutlined/>} onClick={() => navigate('/specs/edit/' + record.key)}/>
                    <Button type='text' icon={<DeleteOutlined/>} onClick={() => specs.deleteItem(record.key)}/>
                    <Button
                        type='text'
                        icon={<CloseOutlined  onClick={() => {
                            const alreadySelectedIssue = issues.items.find(issue => issue.key === modalIssueKey);
                            issues.editItem(modalIssueKey, {...alreadySelectedIssue, related_spec_key: alreadySelectedIssue?.related_spec_key.filter(spec_key => spec_key !== record.key)})
                        }}/>}
                    />
                </Space>
            )
        }
    ]

    const columns: TableColumnsType<IssueType> = [
        {
            key: 'progress',
            title: 'Progress',
            dataIndex: 'progress',
            filters: [
                { text: ProgressTypeEnum.New, value: ProgressTypeEnum.New },
                { text: ProgressTypeEnum.InProgress, value: ProgressTypeEnum.InProgress },
                { text: ProgressTypeEnum.Resolved, value: ProgressTypeEnum.Resolved },
                { text: ProgressTypeEnum.Closed, value: ProgressTypeEnum.Closed },
            ], 
            onFilter: (value: any, record: IssueType) => record.progress === value,
            render: (status: string, record: IssueType) => (
                <Select defaultValue={status} style={{ width: 120 }} onChange={(value) => set_progress(record.key, value as ProgressTypeEnum)}>
                    <Select.Option value={ProgressTypeEnum.New}>New</Select.Option>
                    <Select.Option value={ProgressTypeEnum.InProgress}>In Progress</Select.Option>
                    <Select.Option value={ProgressTypeEnum.Resolved}>Resolved</Select.Option>
                    <Select.Option value={ProgressTypeEnum.Closed}>Closed</Select.Option>
                </Select>
            )
        },
        {
            key: 'outage_date',
            title: 'Outage date',
            dataIndex: 'outage_date',
            filters: issues.items.map(issue => ({ text: issue.outage_date.format('YYYY/MM/DD'), value: issue.outage_date.format('YYYY/MM/DD') })).filter(
                (item, index, self) => index === self.findIndex((t) => t.value === item.value)
            ),
            filterSearch: true,
            onFilter: (value: any, record: IssueType) => record.outage_date.format('YYYY/MM/DD').includes(value),
            defaultSortOrder: 'descend',
            sorter: (a: IssueType, b: IssueType) => a.outage_date.diff(b.outage_date),
            render: (outage_date: Dayjs) => (
                <>
                    <p>{outage_date.format('YYYY/MM/DD')}</p>
                </>
            )
        },
        {
            key: 'ticket_id',
            title: 'Ticket ID',
            dataIndex: 'ticket_id',
            filters: issues.items.map(issue => ({ text: issue.ticket_id, value: issue.ticket_id })).filter(
                (item, index, self) => index === self.findIndex((t) => t.value === item.value)
            ),
            filterSearch: true,
            onFilter: (value: any, record: IssueType) => record.ticket_id.includes(value),
        },
        {
            key: 'title',
            title: 'Title',
            dataIndex: 'title',
            filters: issues.items.map(issue => ({ text: issue.title, value: issue.title })).filter(
                (item, index, self) => index === self.findIndex((t) => t.value === item.value)
            ),
            filterSearch: true,
            onFilter: (value: any, record: IssueType) => record.title.includes(value),
        },
        {
            key: 'system_tags',
            title: 'Systems',
            dataIndex: 'system_tags',
            filters: issues.items.map(issue => issue.system_tags.map(tag => ({ text: tag, value: tag }))).flat().filter(
                (item, index, self) => index === self.findIndex((t) => t.value === item.value)
            ),
            filterSearch: true,
            onFilter: (value: any, record: IssueType) => record.system_tags.includes(value),
            render: (tags: string[]) => (
                <>
                    {tags.map(tag => {
                        const color = tag.length > 7 ? 'geekblue' : 
                                      tag.length > 5 ? 'green' :
                                      tag.length > 3 ? 'orange' : 'red'
                        return (
                            <Tag color={color} key={tag}>
                                {tag.toUpperCase()}
                            </Tag>
                        )
                    })}
                </>
            )
        },
        {
            key: 'error_source_tags',
            title: 'Error Source',
            dataIndex: 'error_source_tags',
            filters: issues.items.map(issue => issue.error_source_tags.map(tag => ({ text: tag, value: tag }))).flat().filter(
                (item, index, self) => index === self.findIndex((t) => t.value === item.value)
            ),
            filterSearch: true,
            onFilter: (value: any, record: IssueType) => record.error_source_tags.includes(value),
            render: (tags: string[]) => (
                <>
                    {tags.map(tag => {
                        const color = tag.length > 7 ? 'geekblue' : 
                                      tag.length > 5 ? 'green' :
                                      tag.length > 3 ? 'orange' : 'red'
                        return (
                            <Tag color={color} key={tag}>
                                {tag.toUpperCase()}
                            </Tag>
                        )
                    })}
                </>
            )
        },
        {
            key: 'error_category_tags',
            title: 'Error Category',
            dataIndex: 'error_category_tags',
            filters: issues.items.map(issue => issue.error_category_tags.map(tag => ({ text: tag, value: tag }))).flat().filter(
                (item, index, self) => index === self.findIndex((t) => t.value === item.value)
            ),
            filterSearch: true,
            onFilter: (value: any, record: IssueType) => record.error_category_tags.includes(value),
            render: (tags: string[]) => (
                <>
                    {tags.map(tag => {
                        const color = tag.length > 7 ? 'geekblue' : 
                                      tag.length > 5 ? 'green' :
                                      tag.length > 3 ? 'orange' : 'red'
                        return (
                            <Tag color={color} key={tag}>
                                {tag.toUpperCase()}
                            </Tag>
                        )
                    })}
                </>
            )
        },
        {
            key: 'priority',
            title: 'Priority',
            dataIndex: 'priority',
            filters: [
                { text: PriorityTypeEnum.High, value: PriorityTypeEnum.High },
                { text: PriorityTypeEnum.Middle, value: PriorityTypeEnum.Middle },
                { text: PriorityTypeEnum.Low, value: PriorityTypeEnum.Low },
            ],
            filterSearch: true,
            onFilter: (value: any, record: IssueType) => record.priority.includes(value),
        },
        {
            key: 'elapsed_days',
            title: 'Elapsed days',
            dataIndex: 'elapsed_days',
            sorter: (a: IssueType, b: IssueType) => a.elapsed_days - b.elapsed_days,
            render: (elapsed_days: number, record: IssueType) => (
                record.progress === ProgressTypeEnum.New && elapsed_days >= 7 ? <p style={{color: 'gold'}}>{elapsed_days}</p> : <p style={{color: 'black'}}>{elapsed_days}</p>
            )
        },
        {
            key: 'remaining_days',
            title: 'Remaining days',
            dataIndex: 'remaining_days',
            sorter: (a: IssueType, b: IssueType) => a.remaining_days - b.remaining_days,
            render: (remaining_days: number) => (
                remaining_days <= 0 ? <p style={{color: 'red'}}>{remaining_days}</p> : 
                remaining_days < 7 ? <p style={{color: 'orange'}}>{remaining_days}</p> :
                <p style={{color: 'black'}}>{remaining_days}</p>
            )
        },
        {
            key: 'action',
            title: 'Action',
            dataIndex: 'action',
            fixed: 'right',
            render: (text:String, record: IssueType, index:Number) => (
                <Space size="middle">
                    <Button type='text' icon={<EyeOutlined/>} onClick={() => navigate('/issues/edit/' + record.key)}/>
                    <Button type='text' icon={<DeleteOutlined onClick={() => issues.deleteItem(record.key)} />}/>
                    <Button 
                        type='text' 
                        icon={<SisternodeOutlined />} 
                        onClick={() => {
                            setModalIssueKey(record.key);
                            const alreadySelectedIssue = issues.items.find(issue => issue.key === record.key);
                            setSelectedRowKeys(alreadySelectedIssue?.related_spec_key || []);
                            setIsModalOpen(true);
                        }}/>
                </Space>
            )
        }
    ]
    return (
        <div>
            <Row style={{ marginBottom: 24 }}>
                <Col span={12}>
                    <h1>Issues</h1>
                </Col>
                <Col span={12} style={{ textAlign: 'right' }}>
                    <Button type='primary' icon={<PlusSquareOutlined/>} onClick={handleAddEmptyIssue} >
                        Create new Issue
                    </Button>
                </Col>
            </Row>
            <Table<IssueType> 
                columns={columns} 
                expandable={{
                    expandedRowRender: (record: IssueType) => (
                        <div>
                            <Typography.Title level={5} style={{ marginBottom: 12 }}>Related Specs</Typography.Title>
                            <Table<SpecType>
                                columns={spec_columns} 
                                dataSource={specs.items.filter(spec => record.related_spec_key.includes(spec.key))} 
                                scroll={{ x: 'max-content', y: 'max-content' }}
                            />
                        </div>
                    ),
                    rowExpandable: (record: IssueType) => specs.items.some(spec => record.related_spec_key.includes(spec.key)),
                }}
                dataSource={issues.items} 
                scroll={{ x: 'max-content', y: 'max-content' }}
            />
            <Modal
                open={isModalOpen}
                onOk={() => {
                    issues.editItem(modalIssueKey, {
                        ...issues.items.filter(issue => issue.key === modalIssueKey)[0],
                        related_spec_key: selectedRowKeys.map(key => key.toString())
                    });
                    setIsModalOpen(false);
                }}
                onCancel={() => setIsModalOpen(false)}
                width='100%'
                height='100%'
            >
                <Table<SpecType>
                    rowSelection={{
                        type: 'checkbox' as const,
                        onChange: (selectedRowKeys) => setSelectedRowKeys(selectedRowKeys)
                    }}
                    columns={spec_columns} 
                    dataSource={specs.items} 
                    scroll={{ x: 'max-content', y: 'max-content' }}
                />
            </Modal>
        </div>
    )
}